#!/usr/bin/env python3
"""Generate MuLIB's architecture snapshot from the supplied dsymspec directory.

Generation only: requires PyYAML and jsonschema. Runtime C has neither dependency.
Never executes encoder pseudo-code or imports backend JSON. --check checks freshness;
--json ARCH writes the runtime-loadable, normalized JSON for one architecture.
"""
import argparse
import hashlib
import json
from pathlib import Path
import re
import sys

import jsonschema
import yaml

ROOT = Path(__file__).resolve().parent.parent
OUTPUT = ROOT / 'include/mulib-dsymspec-data.inc'


class UniqueLoader(yaml.SafeLoader):
    """Do not silently accept duplicate YAML mapping keys."""


def unique_mapping(loader, node):
    result = {}
    for key_node, value_node in node.value:
        key = loader.construct_object(key_node)
        if key in result:
            raise ValueError('duplicate YAML key: ' + str(key))
        result[key] = loader.construct_object(value_node)
    return result


UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG, unique_mapping)


def resolve_encodings(doc):
    """Resolve only the audited asmtk templates, not arbitrary pseudo-code."""
    result = []
    encoders = {entry['name']: entry for entry in doc.get('encoders', [])}
    for source in doc.get('asmtk', {}).get('encodings', []):
        out = dict(source)
        out.setdefault('group', 0)
        out.setdefault('reg_operand', 1)
        out.setdefault('rex_w', True)
        if 'encoder' in source:
            opcode = []
            for line in encoders[source['encoder']]['body'].strip().splitlines():
                line = line.strip()
                emit = re.fullmatch(r'EMIT8 (0x[0-9A-Fa-f]+)( \+ dst)?', line)
                modrm = re.fullmatch(r'EMIT_MODRM (dst|src|[0-7]), (dst|src)', line)
                reloc = re.fullmatch(r'EMIT_RELOCATION sym, ([A-Za-z0-9_]+)', line)
                if emit:
                    opcode.append(int(emit[1], 16))
                elif modrm:
                    if modrm[1].isdigit():
                        out['group'] = int(modrm[1])
                    else:
                        out['reg_operand'] = 0 if modrm[1] == 'dst' else 1
                elif reloc:
                    out['relocation_name'] = reloc[1]
                elif not re.fullmatch(r'EMIT_IMM (4|8), (0|imm)', line):
                    raise ValueError('unsupported asmtk encoder template: ' + line)
            if source['form'] != 'Fixed' and opcode and opcode[0] == 0x48:
                opcode.pop(0)  # The assembler constructs REX from operand encodings.
            if not 1 <= len(opcode) <= 3:
                raise ValueError('unsupported opcode length: ' + source['encoder'])
            out['opcode'] = opcode
        result.append(out)
    return result


def exact_integers(value):
    # JSON DOM numbers are doubles. Preserve the two large source bounds exactly
    # as decimal strings instead of silently rounding their metadata.
    if type(value) is int and abs(value) > 9007199254740991:
        return str(value)
    if isinstance(value, list):
        return [exact_integers(item) for item in value]
    if isinstance(value, dict):
        return {key: exact_integers(item) for key, item in value.items()}
    return value


def documents():
    schema_bytes = (ROOT / 'dsymspec/schema/dsymspec.schema.json').read_bytes()
    validator = jsonschema.Draft202012Validator(json.loads(schema_bytes))
    for path in sorted((ROOT / 'dsymspec').glob('*.dsymspec.yaml')):
        raw = path.read_bytes()
        doc = yaml.load(raw, Loader=UniqueLoader)
        validator.validate(doc)
        normalized = resolve_encodings(doc)
        doc = exact_integers(doc)
        doc['_mulib_codegen'] = {
            'version': 1,
            'source': 'dsymspec/' + path.name,
            'source_sha256': hashlib.sha256(raw).hexdigest(),
            'schema_sha256': hashlib.sha256(schema_bytes).hexdigest(),
            'encodings': normalized,
        }
        yield path.name.removesuffix('.dsymspec.yaml'), doc


def render(docs):
    lines = ['/* Generated by tools/dsymspec_generate.py; do not edit.',
             ' * Source: repository dsymspec architecture YAML files and schema.',
             ' * Backend files are references only, never automatically opened. */']
    for index, (_, doc) in enumerate(docs):
        text = json.dumps(doc, ensure_ascii=True, separators=(',', ':'), sort_keys=True)
        lines.append('static const char *const mulib_dsymspec_chunks_%d_[] = {' % index)
        # Each translation-time string is under ISO C's 4095 character minimum.
        for start in range(0, len(text), 1000):
            lines.append('    ' + json.dumps(text[start:start + 1000]) + ',')
        lines.append('    NULL\n};')
    lines.append('static const mulib_dsymspec_builtin_ mulib_dsymspec_builtins_[] = {')
    for index, (name, _) in enumerate(docs):
        lines.append('    {"%s", mulib_dsymspec_chunks_%d_},' % (name, index))
    lines.append('};\n')
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    parser.add_argument('--json', metavar='ARCH')
    args = parser.parse_args()
    docs = list(documents())
    if args.json:
        matches = [doc for name, doc in docs if name == args.json]
        if not matches:
            parser.error('unknown architecture: ' + args.json)
        print(json.dumps(matches[0], ensure_ascii=True, sort_keys=True, separators=(',', ':')))
        return 0
    content = render(docs)
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            print(str(OUTPUT) + ': stale snapshot', file=sys.stderr)
            return 1
    else:
        OUTPUT.write_text(content)
    return 0


if __name__ == '__main__':
    sys.exit(main())
